{
  "claims": [
    {
      "claim": "There are two types of Amazon Bedrock Knowledge Bases.",
      "label": "supported"
    },
    {
      "claim": "Managed Knowledge Base: Amazon Bedrock manages the underlying data ingestion, indexing, storage, and retrieval infrastructure.",
      "label": "supported"
    },
    {
      "claim": "Managed Knowledge Base allows you to focus on your application and agent logic.",
      "label": "supported"
    },
    {
      "claim": "Managed Knowledge Base offers advanced capabilities including ingestion of multi-modal data, storage auto-scaling, agentic retrieval for multi-hop reasoning, and more.",
      "label": "supported"
    },
    {
      "claim": "Managed Knowledge Base provides key customizations to tailor agents to your use case.",
      "label": "supported"
    },
    {
      "claim": "Managed Knowledge Base integrates natively with AgentCore Gateway, enabling any MCP-compatible agent framework to discover and invoke your Knowledge Base as a tool without custom code.",
      "label": "supported"
    },
    {
      "claim": "Managed Knowledge Base supports connectors for various data sources like Amazon S3, SharePoint, Confluence, Google Drive, OneDrive, and Web Crawler.",
      "label": "supported"
    },
    {
      "claim": "Managed Knowledge Base includes document-level permission filtering using Access Control Lists (except for Web Crawler) at retrieval time.",
      "label": "supported"
    },
    {
      "claim": "The Smart Parsing feature auto-selects parsing strategy per document type.",
      "label": "supported"
    },
    {
      "claim": "Agentic Retrieval supports multi-hop reasoning.",
      "label": "supported"
    },
    {
      "claim": "Native integration with AgentCore Observability offers built-in monitoring, retrieval traces, agentic traces, and per-knowledge base metrics.",
      "label": "supported"
    },
    {
      "claim": "Customer-managed Knowledge Base enables you to set up and manage your own RAG pipeline, including the vector store (such as Amazon OpenSearch Serverless, Amazon Aurora, and Amazon Neptune).",
      "label": "supported"
    },
    {
      "claim": "Customer-managed Knowledge Base gives you full control over data ingestion, parsing, indexing, and storage configurations.",
      "label": "supported"
    },
    {
      "claim": "With Customer-managed Knowledge Base you will need to set up and manage related infrastructure and configurations such as parsing for multimodal data.",
      "label": "supported"
    },
    {
      "claim": "Several capabilities such as third-party connectors, document-level permissions, and native AgentCore Gateway integration are only available for Managed Knowledge Bases.",
      "label": "supported"
    }
  ]
}
